use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Item {
    kind: string,
    a: int,
    b: int,
    c: int,
}

impl Shape for Item {
    fn name(self) -> string {
        self.kind
    }
    fn corners(self) -> int {
        if self.kind == "rtri" { 3 } else { 4 }
    }
    fn double_area(self) -> int {
        if self.kind == "square" {
            2 * self.a * self.a
        } else if self.kind == "rect" {
            2 * self.a * self.b
        } else if self.kind == "rtri" {
            self.a * self.b
        } else {
            (self.a + self.b) * self.c
        }
    }
}

fn num(parts: Vec<string>, i: int) -> int {
    if i < parts.len() as int {
        parts[i as usize].parse::<int>().unwrap_or(0)
    } else {
        0
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = ""
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let it = Item { kind: parts[0], a: num(parts, 1), b: num(parts, 2), c: num(parts, 3) }
        let d = it.double_area()
        println("${it.name()} corners=${it.corners()} area2=${d}")
        total += d
        if d > best {
            best = d
            best_name = it.name()
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

